const crypto = require('crypto');
const errorData = $input.first().json;
const execution = errorData.execution || {};
const workflow = errorData.workflow || {};
const secret = $env.TRUV_LEDGEROS_WEBHOOK_SECRET || 'dev-n8n-webhook-hmac-sha256-secret';

// Redact any possible credentials or secrets in error messages
let rawMessage = errorData.execution?.error?.message || 'Workflow execution failed';
rawMessage = rawMessage.replace(/Bearer\s+[A-Za-z0-9-_.]+/gi, 'Bearer [REDACTED]');
rawMessage = rawMessage.replace(/key=[A-Za-z0-9-_]+/gi, 'key=[REDACTED]');

const correlationId = `err_${execution.id || Date.now()}`;
const tenantId = execution.data?.resultData?.runData?.['LedgerOS Event Webhook']?.[0]?.data?.main?.[0]?.[0]?.json?.body?.tenantId || 'system';
const timestamp = Date.now().toString();

const payloadObj = {
  action: 'RECORD_FAILURE_ALERT',
  tenantId,
  correlationId,
  idempotencyKey: `idemp_err_${correlationId}`,
  payload: {
    workflowName: workflow.name || 'n8n Automation',
    executionId: execution.id,
    errorSummary: rawMessage.slice(0, 500),
    failedAt: new Date().toISOString()
  }
};

const payloadString = JSON.stringify(payloadObj);
const hmac = crypto.createHmac('sha256', secret);
hmac.update(`${timestamp}.${payloadString}`);
const signature = `sha256=${hmac.digest('hex')}`;

return [{
  json: {
    body: payloadObj,
    signature,
    timestamp
  }
}];
